import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def transform(g):
    from collections import Counter, deque
    cnt=Counter(v for r in g for v in r)
    bg=cnt.most_common(1)[0][0]
    h,w=len(g),len(g[0])
    filled=[[v==1 for v in r] for r in g]
    q=deque((r,c) for r in range(h) for c in range(w) if g[r][c]==1)
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r,c+1)):
            if 0<=nr<h and 0<=nc<w and g[nr][nc]==bg and not filled[nr][nc]:
                filled[nr][nc]=True; q.append((nr,nc))
    return [[4 if g[r][c]==1 else (1 if filled[r][c] else g[r][c]) for c in range(w)] for r in range(h)]

exp=G['Demo pair 1 output']; got=transform(G['Demo pair 1 input'])
print(got==exp)
for r in got: print(' '.join(map(str,r)))

